<?php

namespace Agent\AgentBundle\Repository;

//use Doctrine\ORM\Query\Expr\Join;
use Doctrine\ORM\Query\AST\Join;

/**
 * AgentRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class AffecterRepository extends \Doctrine\ORM\EntityRepository {
    protected $container;

    public function setContainer(ContainerInterface $container)
    {
        $this->container = $container;
    }
    public function AffecterImputer($type, $user = null) {
        # code...
        $qb = $this->createQueryBuilder('a')
                ->leftJoin('AgentBundle:Imputation', 'i', 'WITH', 'a.id = i.objetId')
                ->innerJoin('AgentBundle:Agent', 'ag', 'WITH', 'a.id = ag.affecter');

        /*
         * $type
         * *1=Affecation a imputer
          ==2= Affecation reçues
         */
        switch ($type) {
            case 1:
                # code...
                $qb
                        ->select(
                                'ag.matricule as matAffecter', 'ag.nom as nomAffecter', 'ag.prenoms as prenomsAffecter', 'a.id as id', 'a.etatAffectation as affecter_etat', 'i.id as imputation_id', 'i.etat as imputation_etat', 'i.etatTraitement as imputation_etat_trt', 'i.dateImputation as date_imputation', 'i.dateTraitement as date_trt')
                        ->where('i.etat = 0 or i.etat is null')
                        ->andwhere('a.etatSave = 0')
                        ->andWhere('a.etatAffectation = 0')
                        ->orderBy('a.id', 'DESC');

                break;
            case 2:
                # code...
                $agent = $user->getAgent()->getMatricule();
                $qb
                        ->select(
                                'agt.matricule as matImputer', 'agt.nom as nomImputer', 'agt.prenoms as prenomsImputer', 'ag.matricule as matAffecter', 'ag.nom as nomAffecter', 'ag.prenoms as prenomsAffecter', 'a.id as id', 'a.etatAffectation as affecter_etat', 'i.id as imputation_id', 'i.etat as imputation_etat', 'i.etatTraitement as imputation_etat_trt', 'i.dateImputation as date_imputation', 'i.dateTraitement as date_trt', 'i.actions as action_affectation', 'i.objetId as objet_id', 'dir.id as id_direction', 'dir.libDirect')
                        ->innerJoin('i.matImputer', 'agt')
                        ->leftJoin('AgentBundle:Direction', 'dir', 'WITH', 'dir.id = ag.Direction')
                        ->where('i.matImputer = :agent')
                        ->andWhere('i.etatTraitement = 0')
                        ->setParameter('agent', $agent)
                        ->orderBy('i.id', 'DESC');

                break;

            default:
                # code...
                break;
        }

        //dump($qb->getQuery()->getResult()); die;
        return $qb->getQuery()->getResult();
    }

    public function AffecterIndex($user, $etatAffectation, $etatImputation, $signeNote = null, $signeCertificat = null, $d = null, $deleguation=['retour'=>2, 'service'=>null]) {

        //dump($deleguation['retour']); die;
        
        if (($user->hasRole("ROLE_RESPO_SRHMG") and $d != 1)  or $deleguation['retour'] == 0) {

            $qb = $this->createQueryBuilder('a')
                    ->select('agt.matricule', 'agt.nom', "CONCAT(agt.nom, ' née ', agt.nomJeuneFille) AS nom_marie", "CONCAT(agt.nom, ' ', agt.prenoms) AS nom_celibataire", 'agt.prenoms', 'agt.nomJeuneFille', 'agt.datePriseServiceDge', 'dir.libDirect as direction', 'a.id as id', 'a.etatAffectation as affecter_etat', 'a.signeNote', 'a.signeCertificat', 'i.id as imputation_id', 'i.etat as imputation_etat')
                    ->leftJoin('AgentBundle:Imputation', 'i', 'WITH', 'a.id = i.objetId')
                    ->innerJoin('AgentBundle:Agent', 'agt', 'WITH', 'a.id = agt.affecter')
                    ->leftJoin('AgentBundle:Direction', 'dir', 'WITH', 'dir.id = agt.Direction')
                    ->where('a.etatSave = 0')
                    ->andWhere('a.etatAffectation = :EtatAffectation');
                        if($deleguation['service'] and $etatAffectation != 0){
                            $qb->andWhere($qb->expr()->In('agt.Direction', ':sercice'))
                            ->setParameter('sercice',explode(",", $deleguation['service']));
                        }
                    $qb->setParameter('EtatAffectation', $etatAffectation);
 
 //dump($qb->getQuery()->getResult());die;




            if (!is_null($signeNote)) {
                //dump(1);

                $qb->andWhere('a.signeNote = :SigneNote')
                        ->setParameter('SigneNote', $signeNote);
            }
            if (!is_null($signeCertificat)) {
                //dump(2);

                $qb->andWhere('a.signeCertificat = :SigneCertificat')
                        ->setParameter('SigneCertificat', $signeCertificat);
            }

            $qb->orderBy('i.id', 'DESC');

            if ($etatImputation == 0) { //dump(1);
                $qb->andWhere('i.etat = :EtatImputation or i.etat is null')
                        ->setParameter('EtatImputation', $etatImputation);
            } else {
                $qb->andWhere('i.etat = :EtatImputation')->setParameter('EtatImputation', $etatImputation);
            }
            return $qb->getQuery()->getResult();
        } elseif (($user->hasRole("ROLE_RESPO") and $user->getAgent()->getFonction() and in_array($user->getAgent()->getFonction()->getId(), [5,7,9,10])) or $user->hasRole("ROLE_SAAF")) {

            if ($user->getAgent()->getDirection()) {
                $direction = $user->getAgent()->getDirection()->getId();
            }
            if ($user->getAgent()->getFonction()) {
                $fct = $user->getAgent()->getFonction()->getId();
            }

            $qb = $this->createQueryBuilder('a')
                    ->join('a.agent', 'd')
                    ->addSelect('d')
                    ->where('d.Direction = :Direction')
                    ->andWhere('a.etatSave = 0')
                    ->andWhere('a.signeNote = 1');
                    if ($fct == 10){
                         $qb->setParameter("Direction", 16);
                    }else{
                         $qb->setParameter("Direction", $direction);
                    }
                   
            if (!is_null($etatAffectation)) {
                $qb->andWhere('a.etatAffectation = :EtatAffectation')
                        ->setParameter('EtatAffectation', $etatAffectation);
            }
            if (!is_null($signeCertificat)) {
                $qb->andWhere('a.signeCertificat = :SigneCertificat')
                        ->setParameter('SigneCertificat', $signeCertificat);
            }

            $qb->orderBy('a.id', 'DESC');
            $valid = $qb->getQuery()->getResult();
            return $valid;
        }
    }

}
